      const inputId = `${questionId}-${option.value}`;
      return `
        <label class="option" for="${inputId}">
          <input id="${inputId}" type="checkbox" name="${questionId}" value="${option.value}">
          <span class="option-label">
            ${String.fromCharCode(65 + index)}. ${option.label}
          </span>
        </label>
      `;
    }

    function questionTemplate(question, index) {
      const helpId = question.help ? `${question.id}-help` : '';
      const describedBy = question.help ? ` aria-describedby="${helpId}"` : '';

      return `
        <div class="form-field">
          <fieldset${describedBy}>
            <legend>${index + 1}. ${question.title}</legend>
            ${question.help ? `<p id="${helpId}" class="help-text">${question.help}</p>` : ''}
            <div class="options" role="group" aria-label="${question.title}">
              ${question.options.map((option, optionIndex) => optionTemplate(question.id, option, optionIndex)).join('')}
            </div>
          </fieldset>
        </div>
      `;
    }

    function appTemplate() {
      return `
        <main id="maincontent" class="page-shell" tabindex="-1">
          <header class="hero">
            <p class="eyebrow">Computer languages</p>
            <h1>Language Basics Quiz</h1>
