 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <div id="app"></div>

   <script>
     const quizData = [
       {
         id: 'languages',
         title: 'Which of these are programming languages?',
         help: 'Select all that apply. More than one answer is correct.',
         options: [
           { value: 'javascript', label: 'JavaScript' },
           { value: 'python', label: 'Python' },
           { value: 'html', label: 'HTML' },
           { value: 'css', label: 'CSS' }
         ],
         correct: ['javascript', 'python']
       },
       {
         id: 'typed',
         title: 'Which of these are statically typed languages?',
         options: [
           { value: 'typescript', label: 'TypeScript' },
           { value: 'rust', label: 'Rust' },
           { value: 'bash', label: 'Bash' },
           { value: 'markdown', label: 'Markdown' }
         ],
         correct: ['typescript', 'rust']
       },
       {
         id: 'dsl',
         title: 'Which of these are markup or query languages?',
         options: [
           { value: 'sql', label: 'SQL' },
           { value: 'html', label: 'HTML' },
           { value: 'png', label: 'PNG' },
           { value: 'http', label: 'HTTP' }
         ],
         correct: ['sql', 'html']
       }
     ];

     const app = document.getElementById('app');

     function optionTemplate(questionId, option, index) {
       const inputId = `${questionId}-${option.value}`;
       return `
         <label class="option" for="${inputId}">
           <input id="${inputId}" type="checkbox" name="${questionId}" value="${option.value}">
           <span class="option-label">
             ${String.fromCharCode(65 + index)}. ${option.label}
           </span>
         </label>
       `;
     }

     function questionTemplate(question, index) {
       const helpId = question.help ? `${question.id}-help` : '';
       const describedBy = question.help ? ` aria-describedby="${helpId}"` : '';

         return `
         <div class="form-field">
           <fieldset${describedBy}>
             <legend>${index + 1}. ${question.title}</legend>
             ${question.help ? `<p id="${helpId}" class="help-text">${question.help}</p>` : ''}
             <div class="options">
               ${question.options.map((option, optionIndex) => optionTemplate(question.id, option, optionIndex)).join('')}
             </div>
           </fieldset>
         </div>
       `;
     }

     function appTemplate() {
       return `
         <main id="maincontent" class="page-shell" tabindex="-1">
           <header class="hero">
             <p class="eyebrow">Computer languages</p>
             <h1>Language Basics Quiz</h1>
             <p class="lede">
               Test what you know about programming languages, typing, and the different kinds of language tools used in computing.
             </p>
           </header>

           <section class="quiz-card" aria-labelledby="quiz-heading">
             <h2 id="quiz-heading" class="sr-only">Quiz questions</h2>

             <form id="quiz-form" novalidate>
               <div class="quiz-grid">
                 ${quizData.map(questionTemplate).join('')}
               </div>

               <div class="actions">
                 <button type="submit">Check answers</button>
                 <p class="footnote">You can select more than one answer in each question.</p>
               </div>

               <div id="quiz-status" class="status" role="status" aria-live="polite" aria-atomic="true">
                 Choose your answers, then check them to see your score.
               </div>
             </form>
           </section>
         </main>
       `;
     }

     app.innerHTML = appTemplate();

     const form = document.getElementById('quiz-form');
     const status = document.getElementById('quiz-status');

     function selectedValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
     }

     function matchesAnswer(selected, correct) {
       if (selected.length !== correct.length) return false;
       const selectedSet = new Set(selected);
       return correct.every((value) => selectedSet.has(value));
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const results = quizData.map((question) => {
         const selected = selectedValues(question.id);
         const correct = question.correct;
         const isCorrect = matchesAnswer(selected, correct);
         return { question, selected, isCorrect };
       });

       const score = results.filter((result) => result.isCorrect).length;
       status.dataset.state = score === quizData.length ? 'success' : 'info';
       status.textContent = `Score: ${score} out of ${quizData.length}. ${score === quizData.length ? 'Perfect!' : 'Review your selections and try again.'}`;
     });
   </script>
